#!/usr/bin/env python3
"""Run ping tests sequentially to avoid connection issues."""
import time
from netmiko import ConnectHandler

def linux_conn(host):
    return ConnectHandler(device_type="linux", host=host, username="root", password="alpine", timeout=30, banner_timeout=30)

hosts = {
    "B1-PC1": ("192.168.122.31", "10.1.1.10"),
    "B1-PC2": ("192.168.122.32", "10.1.1.11"),
    "B2-PC1": ("192.168.122.33", "10.1.2.10"),
    "B2-PC2": ("192.168.122.34", "10.1.2.11"),
    "B3-PC1": ("192.168.122.35", "10.1.3.10"),
    "B3-PC2": ("192.168.122.36", "10.1.3.11"),
    "B4-PC1": ("192.168.122.37", "10.2.1.10"),
    "B4-PC2": ("192.168.122.38", "10.2.1.11"),
    "B4-PC3": ("192.168.122.39", "10.2.2.10"),
    "B4-PC4": ("192.168.122.40", "10.2.2.11"),
}

non_guest = ["B1-PC1", "B1-PC2", "B2-PC1", "B2-PC2", "B3-PC1", "B3-PC2", "B4-PC1", "B4-PC2"]
guest = ["B4-PC3", "B4-PC4"]

ng_pass = 0; ng_fail = []
gi_pass = 0; gi_fail = []
gb_pass = 0; gb_fail = []
inet_pass = 0; inet_fail = []

for src_name in list(hosts.keys()):
    mgmt_ip = hosts[src_name][0]
    src_is_guest = src_name in guest
    try:
        conn = linux_conn(mgmt_ip)

        # Ping other hosts
        for tgt_name, (_, tgt_ip) in hosts.items():
            if tgt_name == src_name:
                continue
            tgt_is_guest = tgt_name in guest
            out = conn.send_command(f"ping -c 2 -W 2 {tgt_ip}", read_timeout=15)
            ok = " 0% packet loss" in out

            if not src_is_guest and not tgt_is_guest:
                if ok: ng_pass += 1
                else: ng_fail.append(f"{src_name}->{tgt_name}")
            elif src_is_guest and tgt_is_guest:
                if ok: gi_pass += 1
                else: gi_fail.append(f"{src_name}->{tgt_name}")
            else:
                if not ok: gb_pass += 1
                else: gb_fail.append(f"{src_name}->{tgt_name}")

        # Internet pings
        for tgt in ["8.8.8.8", "1.1.1.1"]:
            out = conn.send_command(f"ping -c 2 -W 3 {tgt}", read_timeout=15)
            ok = " 0% packet loss" in out
            if ok: inet_pass += 1
            else: inet_fail.append(f"{src_name}->{tgt}")

        conn.disconnect()
        print(f"  done {src_name}")
    except Exception as e:
        print(f"  ERROR {src_name}: {e}")

print(f"\nNon-guest to non-guest: {ng_pass}/56 PASS")
if ng_fail: print(f"  FAILURES: {ng_fail}")
print(f"Guest to guest: {gi_pass}/2 PASS")
if gi_fail: print(f"  FAILURES: {gi_fail}")
print(f"Guest/non-guest isolation: {gb_pass}/32 correctly blocked")
if gb_fail: print(f"  LEAKS: {gb_fail}")
print(f"Internet: {inet_pass}/20 PASS")
if inet_fail: print(f"  FAILURES: {inet_fail}")

